import { foreignSyntax } from '../src/validate/rules/content/foreignSyntax.js';

const check = (content: string) =>
  foreignSyntax.check({
    file: 'page.mdx',
    content,
    baseDir: '/',
    frontmatter: {},
    tree: { type: 'root', children: [] },
  });

const messages = (content: string) => check(content).map(({ message }) => message);

describe('foreign-syntax', () => {
  it.each([
    ['GitBook hint', '{% hint style="warning" %}\nCareful\n{% endhint %}\n', '<Warning>'],
    ['Liquid tag', '{% include note.html %}\n', 'snippet import'],
    ['Hugo shortcode', '{{< figure src="a.png" >}}\n', 'Hugo shortcode'],
    ['Liquid variable', 'Version {{ site.version }}\n', 'Liquid variable'],
    ['Liquid filter', '[Home]({{ "/" | relative_url }})\n', 'Liquid variable'],
    ['Docusaurus admonition', ':::tip\nUse it\n:::\n', '<Tip>'],
    ['VitePress admonition with title', '::: warning Heads up\nx\n:::\n', '<Warning>'],
    ['MDC block', '::note\nx\n::\n', 'MDC'],
    ['MkDocs admonition', '!!! note "Title"\n    Body\n', '<Note>'],
    ['MkDocs collapsible', '??? info\n    Body\n', '<Accordion>'],
    ['MkDocs tab', '=== "Python"\n    code\n', '<Tabs>'],
    ['MkDocs snippet in a fence', '```py\n--8<-- "example.py"\n```\n', 'snippet include'],
    ['Kramdown IAL', 'Text\n{: .note }\n', 'Kramdown'],
    ['wiki link', 'See [[Getting Started]].\n', 'wiki link'],
    ['wiki link with label', 'See [[setup|Install]].\n', 'wiki link'],
    ['ReadMe doc link', 'See [setup](doc:setup).\n', 'such as /setup'],
    ['ReadMe ref link in href', '<a href="ref:create-user">x</a>\n', 'such as /create-user'],
    [
      'Docusaurus @site import',
      "import Img from '@site/static/img/a.png';\n\n<img src={Img} />\n",
      '@site',
    ],
  ])('flags %s', (_name, content, expected) => {
    const found = messages(content);
    expect(found).toHaveLength(1);
    expect(found[0]).toContain(expected);
  });

  it('flags each opening GitBook tag once, not its closing tag', () => {
    expect(messages('{% tabs %}\n{% tab title="A" %}\nx\n{% endtab %}\n{% endtabs %}\n')).toEqual([
      expect.stringContaining('use <Tabs>'),
      expect.stringContaining('use <Tab title="…">'),
    ]);
  });

  it.each([
    ['fenced code', '```liquid\n{% hint style="info" %}\n{{ site.title }}\n:::note\n```\n'],
    ['inline code', 'Write `{% hint %}`, `:::note` and `[[Page]]` like this.\n'],
    ['frontmatter', '---\ntitle: "{% hint %}"\ndescription: "[[Page]]"\n---\n\nBody\n'],
    ['MDX expressions', 'Total: {a | b} and {{ x: 1 }.x} and {[[1, 2]].length} and {{page}}\n'],
    ['closing tags and bare fences', ':::\n\n::\n'],
    ['Markdown link after a bracket', '[[1]](#note-1) and [a][ref]\n'],
    ['ordinary prose', 'Use doc: the guide. Wow!!! Equal === sign.\n'],
    ['custom heading ids', '## Install {#install}\n'],
  ])('ignores %s', (_name, content) => {
    expect(messages(content)).toEqual([]);
  });

  it('reports positions in the original file', () => {
    expect(check('---\ntitle: A\n---\n\nText\n  :::note\nx\n:::\n')).toEqual([
      expect.objectContaining({ line: 6, column: 3 }),
    ]);
  });

  it('never offers edits', () => {
    expect(check('{% hint %}\n').every(({ edit }) => edit === undefined)).toBe(true);
  });
});
